def transform(grid):
    from collections import Counter
    flat = [cell for row in grid for cell in row]
    bg_count = Counter(flat)
    background = bg_count.most_common(1)[0][0]
    target = None
    for row in grid:
        for cell in row:
            if cell != background:
                target = cell
                break
        if target is not None:
            break
    if target is None:
        return grid
    cnt = flat.count(target)
    return [[target] for _ in range(cnt)]
